import urllib.request
import time


class RateLimitError(Exception):
    pass


class ServerError(Exception):
    pass


class ClientError(Exception):
    pass


class ConnectionError(Exception):
    pass


class APIClient:
    def __init__(self, base_url: str, timeout: int = 10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path: str) -> str:
        url = self.base_url + path

        # Handle network errors
        for attempt in range(2):
            try:
                req = urllib.request.Request(url)
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    status = response.status
                    body = response.read().decode('utf-8')
                    break
            except urllib.error.URLError:
                if attempt == 0:
                    time.sleep(1)
                else:
                    raise ConnectionError("Connection failed after retries")
        else:
            raise ConnectionError("Connection failed after retries")

        # Handle HTTP errors
        if 400 <= status < 500:
            if status == 429:
                # Rate limit: retry up to 3 times with exponential backoff
                for i in range(3):
                    backoff = 0.5 * (2 ** i)
                    time.sleep(backoff)
                    try:
                        req = urllib.request.Request(url)
                        with urllib.request.urlopen(req, timeout=self.timeout) as response:
                            if response.status == 429:
                                continue
                            else:
                                return response.read().decode('utf-8')
                    except urllib.error.HTTPError as e:
                        if e.code == 429:
                            continue
                        else:
                            return e.read().decode('utf-8')
                raise RateLimitError("Rate limit exceeded after retries")
            else:
                raise ClientError(f"Client error: {status}")
        elif status >= 500:
            # Server error: retry once after 1s
            time.sleep(1)
            try:
                req = urllib.request.Request(url)
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    return response.read().decode('utf-8')
            except urllib.error.HTTPError as e:
                if e.code >= 500:
                    raise ServerError(f"Server error: {e.code}")
                else:
                    return e.read().decode('utf-8')
        else:
            return body
